window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bbcb8ff1de38217f"]={"versions": [{"id": "FIG-bbcb8ff1de38217f", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext des Standardization Templates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Dargestellt sind die Metaklassen zur Definition und Gruppierung von standardisierten Schlüsselwörtern (Keywords) sowie deren Integration in das allgemeine AUTOSAR-M2-Metamodell über <code>ARElement</code> und <code>Identifiable</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der abstrakten Metaklasse <code>ARElement</code> (kursiv gesetzt).</li>\n<li>Fungiert als Aggregationscontainer für Schlüsselwörter auf Paketebene.</li>\n<li><code>Keyword</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der Metaklasse <code>Identifiable</code> (kursiv gesetzt).</li>\n<li>Attribute:</li>\n<li><code>+ abbrName: NameToken</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 1)</li>\n<li><code>+ classification: NameToken [0..<em>]</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 0..</em>)</li>\n<li>Assoziation / Komposition:</li>\n<li>Strenge Komposition (<code>KeywordSet</code> als Ganzes mit ausgefüllter schwarzer Raute).</li>\n<li>Rollenname am Zielende: <code>+keyword</code>.</li>\n<li>Multiplizität am Zielende: <code>0..*</code>. Ein <code>KeywordSet</code> umfasst null bis beliebig viele <code>Keyword</code>-Elemente existenziell abhängig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zur Konfigurations- oder Modellierungszeit instanziiert ein Standardisierungsmodell ein <code>KeywordSet</code> als Top-Level-Element (<code>ARElement</code>). Innerhalb dieses Containers werden einzelne <code>Keyword</code>-Elemente über die Komposition <code>keyword</code> deklariert und eindeutig über ihre <code>Identifiable</code>-Eigenschaften sowie ihr Attribut <code>abbrName</code> und optionale <code>classification</code>-Klassifizierungen spezifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für M2-Autoren, Werkzeugentwickler und Standardisierungs-Workflows in AUTOSAR.</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code> ist als eigenständiges <code>ARElement</code> exportierbar und speicherbar in AUTOSAR-XML-Dateien (ARXML).</li>\n<li>Da <code>Keyword</code> von <code>Identifiable</code> erbt, besitzt jedes Schlüsselwort standardmäßig einen <code>shortName</code> (sowie optionale Identifiable-Metadaten wie UUIDs und Beschreibungen).</li>\n<li><code>abbrName</code> ist obligatorisch (Multiplizität 1) und liefert die standardisierte Abkürzung des Begriffs.</li>\n<li><code>classification</code> erlaubt mehrfache Klassifizierungen (0..*) als Tokens zur semantischen Kategorisierung von Keywords.</li>\n</ul>"}, {"id": "FIG-743dd990bee1c128", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext des Standardization Templates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Dargestellt sind die Metaklassen zur Definition und Gruppierung von standardisierten Schlüsselwörtern (Keywords) sowie deren Integration in das allgemeine AUTOSAR-M2-Metamodell über <code>ARElement</code> und <code>Identifiable</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der abstrakten Metaklasse <code>ARElement</code> (kursiv gesetzt).</li>\n<li>Gekennzeichnet mit den Blueprint-Konzepten bzw. Stereotypen <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> (kursiv gesetzt).</li>\n<li>Fungiert als Aggregationscontainer für Schlüsselwörter auf Paketebene.</li>\n<li><code>Keyword</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der Metaklasse <code>Identifiable</code> (kursiv gesetzt).</li>\n<li>Attribute:</li>\n<li><code>+ abbrName :NameToken</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 1)</li>\n<li><code>+ classification :NameToken [0..<em>]</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 0..</em>)</li>\n<li>Assoziation / Komposition:</li>\n<li>Strenge Komposition (<code>KeywordSet</code> als Ganzes mit ausgefüllter schwarzer Raute).</li>\n<li>Rollenname am Zielende: <code>+keyword</code>.</li>\n<li>Multiplizität am Zielende: <code>0..*</code>. Ein <code>KeywordSet</code> umfasst null bis beliebig viele <code>Keyword</code>-Elemente existenziell abhängig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zur Konfigurations- oder Modellierungszeit instanziiert ein Standardisierungsmodell ein <code>KeywordSet</code> als Top-Level-Element (<code>ARElement</code>). Innerhalb dieses Containers werden einzelne <code>Keyword</code>-Elemente über die Komposition <code>keyword</code> deklariert und eindeutig über ihre <code>Identifiable</code>-Eigenschaften sowie ihr Attribut <code>abbrName</code> und optionale <code>classification</code>-Klassifizierungen spezifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für M2-Autoren, Werkzeugentwickler und Standardisierungs-Workflows in AUTOSAR.</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code> ist als eigenständiges <code>ARElement</code> exportierbar und speicherbar in AUTOSAR-XML-Dateien (ARXML).</li>\n<li>Durch die Klassifizierung mit <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> kann ein <code>KeywordSet</code> als Blaupause (Blueprint) für Standardisierungszwecke definiert und im Blueprint-Workflow abgeleitet bzw. instantiiert werden.</li>\n<li>Da <code>Keyword</code> von <code>Identifiable</code> erbt, besitzt jedes Schlüsselwort standardmäßig einen <code>shortName</code> (sowie optionale Identifiable-Metadaten).</li>\n<li><code>abbrName</code> ist obligatorisch (Multiplizität 1) und liefert die standardisierte Abkürzung des Begriffs.</li>\n<li><code>classification</code> erlaubt mehrfache Klassifizierungen (0..*) als Tokens zur semantischen Kategorisierung von Keywords.</li>\n</ul>"}, {"id": "FIG-b62c78896db26348", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext des Standardization Templates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Dargestellt sind die Metaklassen zur Definition und Gruppierung von standardisierten Schlüsselwörtern (Keywords) sowie deren Integration in das allgemeine AUTOSAR-M2-Metamodell über <code>ARElement</code> und <code>Identifiable</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der abstrakten Metaklasse <code>ARElement</code> (kursiv gesetzt).</li>\n<li>Gekennzeichnet mit den Blueprint-Konzepten bzw. Stereotypen <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> (kursiv gesetzt).</li>\n<li>Fungiert als Aggregationscontainer für Schlüsselwörter auf Paketebene.</li>\n<li><code>Keyword</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der Metaklasse <code>Identifiable</code> (kursiv gesetzt).</li>\n<li>Attribute:</li>\n<li><code>+ abbrName :NameToken</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 1)</li>\n<li><code>+ classification :NameToken [0..<em>]</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 0..</em>)</li>\n<li>Assoziation / Komposition:</li>\n<li>Strenge Komposition (<code>KeywordSet</code> als Ganzes mit ausgefüllter schwarzer Raute).</li>\n<li>Rollenname am Zielende: <code>+keyword</code>.</li>\n<li>Multiplizität am Zielende: <code>0..*</code>. Ein <code>KeywordSet</code> umfasst null bis beliebig viele <code>Keyword</code>-Elemente existenziell abhängig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zur Konfigurations- oder Modellierungszeit instanziiert ein Standardisierungsmodell ein <code>KeywordSet</code> als Top-Level-Element (<code>ARElement</code>). Innerhalb dieses Containers werden einzelne <code>Keyword</code>-Elemente über die Komposition <code>keyword</code> deklariert und eindeutig über ihre <code>Identifiable</code>-Eigenschaften sowie ihr Attribut <code>abbrName</code> und optionale <code>classification</code>-Klassifizierungen spezifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für M2-Autoren, Werkzeugentwickler und Standardisierungs-Workflows in AUTOSAR.</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code> ist als eigenständiges <code>ARElement</code> exportierbar und speicherbar in AUTOSAR-XML-Dateien (ARXML).</li>\n<li>Durch die Klassifizierung mit <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> kann ein <code>KeywordSet</code> als Blaupause (Blueprint) für Standardisierungszwecke definiert und im Blueprint-Workflow abgeleitet bzw. instantiiert werden.</li>\n<li>Da <code>Keyword</code> von <code>Identifiable</code> erbt, besitzt jedes Schlüsselwort standardmäßig einen <code>shortName</code> (sowie optionale Identifiable-Metadaten).</li>\n<li><code>abbrName</code> ist obligatorisch (Multiplizität 1) und liefert die standardisierte Abkürzung des Begriffs.</li>\n<li><code>classification</code> erlaubt mehrfache Klassifizierungen (0..*) als Tokens zur semantischen Kategorisierung von Keywords.</li>\n</ul>"}, {"id": "FIG-b6f71da71683f1c9", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext des Standardization Templates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Dargestellt sind die Metaklassen zur Definition und Gruppierung von standardisierten Schlüsselwörtern (Keywords) sowie deren Integration in das allgemeine AUTOSAR-M2-Metamodell über <code>ARElement</code> und <code>Identifiable</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der abstrakten Metaklasse <code>ARElement</code> (kursiv gesetzt).</li>\n<li>Gekennzeichnet mit den Blueprint-Konzepten bzw. Stereotypen <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> (kursiv gesetzt).</li>\n<li>Fungiert als Aggregationscontainer für Schlüsselwörter auf Paketebene.</li>\n<li><code>Keyword</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der Metaklasse <code>Identifiable</code> (kursiv gesetzt).</li>\n<li>Attribute:</li>\n<li><code>+ abbrName :NameToken</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 1)</li>\n<li><code>+ classification :NameToken [0..<em>]</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 0..</em>)</li>\n<li>Assoziation / Komposition:</li>\n<li>Strenge Komposition (<code>KeywordSet</code> als Ganzes mit ausgefüllter schwarzer Raute).</li>\n<li>Rollenname am Zielende: <code>+keyword</code>.</li>\n<li>Multiplizität am Zielende: <code>0..*</code>. Ein <code>KeywordSet</code> umfasst null bis beliebig viele <code>Keyword</code>-Elemente existenziell abhängig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zur Konfigurations- oder Modellierungszeit instanziiert ein Standardisierungsmodell ein <code>KeywordSet</code> als Top-Level-Element (<code>ARElement</code>). Innerhalb dieses Containers werden einzelne <code>Keyword</code>-Elemente über die Komposition <code>keyword</code> deklariert und eindeutig über ihre <code>Identifiable</code>-Eigenschaften sowie ihr Attribut <code>abbrName</code> und optionale <code>classification</code>-Klassifizierungen spezifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für M2-Autoren, Werkzeugentwickler und Standardisierungs-Workflows in AUTOSAR.</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code> ist als eigenständiges <code>ARElement</code> exportierbar und speicherbar in AUTOSAR-XML-Dateien (ARXML).</li>\n<li>Durch die Klassifizierung mit <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> kann ein <code>KeywordSet</code> als Blaupause (Blueprint) für Standardisierungszwecke definiert und im Blueprint-Workflow abgeleitet bzw. instantiiert werden.</li>\n<li>Da <code>Keyword</code> von <code>Identifiable</code> erbt, besitzt jedes Schlüsselwort standardmäßig einen <code>shortName</code> (sowie optionale Identifiable-Metadaten).</li>\n<li><code>abbrName</code> ist obligatorisch (Multiplizität 1) und liefert die standardisierte Abkürzung des Begriffs.</li>\n<li><code>classification</code> erlaubt mehrfache Klassifizierungen (0..*) als Tokens zur semantischen Kategorisierung von Keywords.</li>\n</ul>"}, {"id": "FIG-876d8103ff4eea0c", "releases": ["R18-10_R4.4.0_R1.5.0", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext des Standardization Templates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Dargestellt sind die Metaklassen zur Definition und Gruppierung von standardisierten Schlüsselwörtern (Keywords) sowie deren Integration in das allgemeine AUTOSAR-M2-Metamodell über <code>ARElement</code> und <code>Identifiable</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der abstrakten Metaklasse <code>ARElement</code> (kursiv gesetzt).</li>\n<li>Gekennzeichnet mit den Blueprint-Konzepten bzw. Stereotypen <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> (kursiv gesetzt).</li>\n<li>Fungiert als Aggregationscontainer für Schlüsselwörter auf Paketebene.</li>\n<li><code>Keyword</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der Metaklasse <code>Identifiable</code> (kursiv gesetzt).</li>\n<li>Attribute:</li>\n<li><code>+ abbrName :NameToken</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 1)</li>\n<li><code>+ classification :NameToken [0..<em>]</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 0..</em>)</li>\n<li>Assoziation / Komposition:</li>\n<li>Strenge Komposition (<code>KeywordSet</code> als Ganzes mit ausgefüllter schwarzer Raute).</li>\n<li>Rollenname am Zielende: <code>+keyword</code>.</li>\n<li>Multiplizität am Zielende: <code>0..*</code>. Ein <code>KeywordSet</code> umfasst null bis beliebig viele <code>Keyword</code>-Elemente existenziell abhängig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zur Konfigurations- oder Modellierungszeit instanziiert ein Standardisierungsmodell ein <code>KeywordSet</code> als Top-Level-Element (<code>ARElement</code>). Innerhalb dieses Containers werden einzelne <code>Keyword</code>-Elemente über die Komposition <code>keyword</code> deklariert und eindeutig über ihre <code>Identifiable</code>-Eigenschaften sowie ihr Attribut <code>abbrName</code> und optionale <code>classification</code>-Klassifizierungen spezifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für M2-Autoren, Werkzeugentwickler und Standardisierungs-Workflows in AUTOSAR.</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code> ist als eigenständiges <code>ARElement</code> exportierbar und speicherbar in AUTOSAR-XML-Dateien (ARXML).</li>\n<li>Durch die Klassifizierung mit <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> kann ein <code>KeywordSet</code> als Blaupause (Blueprint) für Standardisierungszwecke definiert und im Blueprint-Workflow abgeleitet bzw. instantiiert werden.</li>\n<li>Da <code>Keyword</code> von <code>Identifiable</code> erbt, besitzt jedes Schlüsselwort standardmäßig einen <code>shortName</code> (sowie optionale Identifiable-Metadaten).</li>\n<li><code>abbrName</code> ist obligatorisch (Multiplizität 1) und liefert die standardisierte Abkürzung des Begriffs.</li>\n<li><code>classification</code> erlaubt mehrfache Klassifizierungen (0..*) als Tokens zur semantischen Kategorisierung von Keywords.</li>\n</ul>"}, {"id": "FIG-c4634a3ff7116f9d", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext des Standardization Templates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Dargestellt sind die Metaklassen zur Definition und Gruppierung von standardisierten Schlüsselwörtern (Keywords) sowie deren Integration in das allgemeine AUTOSAR-M2-Metamodell über <code>ARElement</code> und <code>Identifiable</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der abstrakten Metaklasse <code>ARElement</code> (kursiv gesetzt).</li>\n<li>Gekennzeichnet mit den Blueprint-Konzepten bzw. Stereotypen <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> (kursiv gesetzt).</li>\n<li>Fungiert als Aggregationscontainer für Schlüsselwörter auf Paketebene.</li>\n<li><code>Keyword</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der Metaklasse <code>Identifiable</code> (kursiv gesetzt).</li>\n<li>Attribute:</li>\n<li><code>+ abbrName :NameToken</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 1)</li>\n<li><code>+ classification :NameToken [0..<em>]</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 0..</em>)</li>\n<li>Assoziation / Komposition:</li>\n<li>Strenge Komposition (<code>KeywordSet</code> als Ganzes mit ausgefüllter schwarzer Raute).</li>\n<li>Rollenname am Zielende: <code>+keyword</code>.</li>\n<li>Multiplizität am Zielende: <code>0..*</code>. Ein <code>KeywordSet</code> umfasst null bis beliebig viele <code>Keyword</code>-Elemente existenziell abhängig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zur Konfigurations- oder Modellierungszeit instanziiert ein Standardisierungsmodell ein <code>KeywordSet</code> als Top-Level-Element (<code>ARElement</code>). Innerhalb dieses Containers werden einzelne <code>Keyword</code>-Elemente über die Komposition <code>keyword</code> deklariert und eindeutig über ihre <code>Identifiable</code>-Eigenschaften sowie ihr Attribut <code>abbrName</code> und optionale <code>classification</code>-Klassifizierungen spezifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für M2-Autoren, Werkzeugentwickler und Standardisierungs-Workflows in AUTOSAR.</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code> ist als eigenständiges <code>ARElement</code> exportierbar und speicherbar in AUTOSAR-XML-Dateien (ARXML).</li>\n<li>Durch die Klassifizierung mit <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> kann ein <code>KeywordSet</code> als Blaupause (Blueprint) für Standardisierungszwecke definiert und im Blueprint-Workflow abgeleitet bzw. instantiiert werden.</li>\n<li>Da <code>Keyword</code> von <code>Identifiable</code> erbt, besitzt jedes Schlüsselwort standardmäßig einen <code>shortName</code> (sowie optionale Identifiable-Metadaten).</li>\n<li><code>abbrName</code> ist obligatorisch (Multiplizität 1) und liefert die standardisierte Abkürzung des Begriffs.</li>\n<li><code>classification</code> erlaubt mehrfache Klassifizierungen (0..*) als Tokens zur semantischen Kategorisierung von Keywords.</li>\n</ul>"}, {"id": "FIG-a504a8f8e2e9015f", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext des Standardization Templates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Dargestellt sind die Metaklassen zur Definition und Gruppierung von standardisierten Schlüsselwörtern (Keywords) sowie deren Integration in das allgemeine AUTOSAR-M2-Metamodell über <code>ARElement</code> und <code>Identifiable</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der abstrakten Metaklasse <code>ARElement</code> (kursiv gesetzt).</li>\n<li>Gekennzeichnet mit den Blueprint-Konzepten bzw. Stereotypen <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> (kursiv gesetzt).</li>\n<li>Fungiert als Aggregationscontainer für Schlüsselwörter auf Paketebene.</li>\n<li><code>Keyword</code>:</li>\n<li>Spezialisierung von bzw. abgeleitet aus der Metaklasse <code>Identifiable</code> (kursiv gesetzt).</li>\n<li>Attribute:</li>\n<li><code>+ abbrName :NameToken</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 1)</li>\n<li><code>+ classification :NameToken [0..<em>]</code> (Sichtbarkeit public, Typ <code>NameToken</code>, Multiplizität 0..</em>)</li>\n<li>Assoziation / Komposition:</li>\n<li>Strenge Komposition (<code>KeywordSet</code> als Ganzes mit ausgefüllter schwarzer Raute).</li>\n<li>Rollenname am Zielende: <code>+keyword</code>.</li>\n<li>Multiplizität am Zielende: <code>0..*</code>. Ein <code>KeywordSet</code> umfasst null bis beliebig viele <code>Keyword</code>-Elemente existenziell abhängig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Zur Konfigurations- oder Modellierungszeit instanziiert ein Standardisierungsmodell ein <code>KeywordSet</code> als Top-Level-Element (<code>ARElement</code>). Innerhalb dieses Containers werden einzelne <code>Keyword</code>-Elemente über die Komposition <code>keyword</code> deklariert und eindeutig über ihre <code>Identifiable</code>-Eigenschaften sowie ihr Attribut <code>abbrName</code> und optionale <code>classification</code>-Klassifizierungen spezifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für M2-Autoren, Werkzeugentwickler und Standardisierungs-Workflows in AUTOSAR.</p>\n<ul class=\"fig-list\">\n<li><code>KeywordSet</code> ist als eigenständiges <code>ARElement</code> exportierbar und speicherbar in AUTOSAR-XML-Dateien (ARXML).</li>\n<li>Durch die Klassifizierung mit <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> kann ein <code>KeywordSet</code> als Blaupause (Blueprint) für Standardisierungszwecke definiert und im Blueprint-Workflow abgeleitet bzw. instantiiert werden.</li>\n<li>Da <code>Keyword</code> von <code>Identifiable</code> erbt, besitzt jedes Schlüsselwort standardmäßig einen <code>shortName</code> (sowie optionale Identifiable-Metadaten).</li>\n<li><code>abbrName</code> ist obligatorisch (Multiplizität 1) und liefert die standardisierte Abkürzung des Begriffs.</li>\n<li><code>classification</code> erlaubt mehrfache Klassifizierungen (0..*) als Tokens zur semantischen Kategorisierung von Keywords.</li>\n</ul>"}], "trans": [{"from": "FIG-bbcb8ff1de38217f", "to": "FIG-743dd990bee1c128", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klasse <code>KeywordSet</code>: Stereotypen bzw. abgeleitete Konzepte <code>«AtpBlueprint»</code> und <code>«AtpBlueprintable»</code> wurden hinzugefügt (kursiv über dem Klassennamen dargestellt).</li>\n</ul>"}, {"from": "FIG-743dd990bee1c128", "to": "FIG-b62c78896db26348", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b62c78896db26348", "to": "FIG-b6f71da71683f1c9", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b6f71da71683f1c9", "to": "FIG-876d8103ff4eea0c", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Klasse <code>Keyword</code>: In den Attributdeklarationen <code>abbrName</code> und <code>classification</code> wurde der Leerraum vor dem Doppelpunkt entfernt (<code>abbrName :NameToken</code> -> <code>abbrName: NameToken</code>, <code>classification :NameToken [0..<em>]</code> -> <code>classification: NameToken [0..</em>]</code>).</li>\n</ul>"}, {"from": "FIG-876d8103ff4eea0c", "to": "FIG-c4634a3ff7116f9d", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c4634a3ff7116f9d", "to": "FIG-876d8103ff4eea0c", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-876d8103ff4eea0c", "to": "FIG-a504a8f8e2e9015f", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
